package com.example.anime import com.lagradost.cloudstream3.* import com.lagradost.cloudstream3.utils.* import com.lagradost.cloudstream3.network.* import org.jsoup.nodes.Element class Anime : MainAPI() { override var name = "Anime" override var mainUrl = "https://animecix.tv/" override var lang = "tr" override val hasMainPage = true override val hasQuickSearch = true override val supportedTypes = setOf(TvType.Movie, TvType.TvSeries) override suspend fun search(query: String): List<SearchResponse> { val searchUrl = "$mainUrl/arama?q=$query" val doc = app.get(searchUrl).document return doc.select(".card, .film-box").mapNotNull { it.toSearchResult() } } private fun Element.toSearchResult(): SearchResponse? { val title = this.selectFirst(".title, h3")?.text() ?: return null val href = fixUrlNull(this.selectFirst("a")?.attr("href")) ?: return null val posterUrl = fixUrlNull(this.selectFirst("img")?.attr("src")) return newMovieSearchResponse(title, href, TvType.TvSeries) { this.posterUrl = posterUrl } } override suspend fun load(url: String): LoadResponse { val doc = app.get(url).document val title = doc.selectFirst("h1.title, .entry-title")?.text() ?: "" val poster = doc.selectFirst(".poster img, .featured-image")?.attr("src") val description = doc.selectFirst(".description, .summary")?.text() val episodes = doc.select(".episodes-list a, .bolumler a").mapNotNull { val epHref = it.attr("href") newEpisode(fixUrlNull(epHref)) { this.name = it.text() } } return newTvSeriesLoadResponse(title, url, TvType.TvSeries, episodes) { this.posterUrl = poster this.plot = description } } override suspend fun loadLinks(data: String, isCasting: Boolean, subtitleCallback: (SubtitleFile) -> Unit, callback: (ExtractorLink) -> Unit): Boolean { val doc = app.get(data).document val iframeSrc = doc.selectFirst("iframe")?.attr("src") ?: return false loadExtractor(iframeSrc, "$mainUrl", subtitleCallback, callback) return true } }